#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libpq-fe.h>

#define MAX_INPUT 4096
#define MAX_QUERY 8192

typedef struct {
    char *name;
    char *value;
    void (*cleanup)(void *);
} Parameter;

typedef struct {
    Parameter **params;
    int count;
    int capacity;
    PGconn *conn;
} QueryContext;

void free_parameter(void *p) {
    Parameter *param = (Parameter *)p;
    if (param) {
        free(param->name);
        free(param->value);
        free(param);
    }
}

QueryContext *create_context(const char *conninfo) {
    QueryContext *ctx = calloc(1, sizeof(QueryContext));
    ctx->capacity = 16;
    ctx->params = calloc(ctx->capacity, sizeof(Parameter *));
    ctx->conn = PQconnectdb(conninfo);
    if (PQstatus(ctx->conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection failed: %s\n", PQerrorMessage(ctx->conn));
        PQfinish(ctx->conn);
        free(ctx->params);
        free(ctx);
        return NULL;
    }
    return ctx;
}

void add_parameter(QueryContext *ctx, const char *name, const char *value) {
    if (ctx->count >= ctx->capacity) {
        ctx->capacity *= 2;
        ctx->params = realloc(ctx->params, ctx->capacity * sizeof(Parameter *));
    }
    Parameter *p = malloc(sizeof(Parameter));
    p->name = strdup(name);
    p->value = strdup(value);
    p->cleanup = free_parameter;
    ctx->params[ctx->count++] = p;
}

/* Process a 'reset' command - frees parameters but keeps dangling pointers */
void process_reset(QueryContext *ctx, int index) {
    if (index >= 0 && index < ctx->count) {
        Parameter *p = ctx->params[index];
        p->cleanup(p);  /* Free the parameter */
        /* BUG: does not NULL out ctx->params[index] or adjust count */
        /* This creates a use-after-free condition */
    }
}

/* Execute query using parameters - may use freed memory */
void execute_query(QueryContext *ctx, const char *template) {
    char query[MAX_QUERY];
    strncpy(query, template, MAX_QUERY - 1);
    query[MAX_QUERY - 1] = '\0';

    for (int i = 0; i < ctx->count; i++) {
        Parameter *p = ctx->params[i]; /* USE-AFTER-FREE: p may be freed */
        char placeholder[64];
        snprintf(placeholder, sizeof(placeholder), "${%s}", p->name);
        char *pos = strstr(query, placeholder);
        if (pos) {
            char tmp[MAX_QUERY];
            size_t prefix_len = pos - query;
            strncpy(tmp, query, prefix_len);
            tmp[prefix_len] = '\0';
            strcat(tmp, p->value); /* Attacker controls value via heap spray */
            strcat(tmp, pos + strlen(placeholder));
            strncpy(query, tmp, MAX_QUERY - 1);
        }
    }

    PGresult *res = PQexec(ctx->conn, query);
    if (PQresultStatus(res) == PGRES_TUPLES_OK) {
        int rows = PQntuples(res);
        for (int i = 0; i < rows; i++) {
            printf("%s\n", PQgetvalue(res, i, 0));
        }
    } else {
        fprintf(stderr, "Query error: %s\n", PQerrorMessage(ctx->conn));
    }
    PQclear(res);
}

int main(int argc, char *argv[]) {
    const char *conninfo = getenv("DATABASE_URL");
    if (!conninfo) conninfo = "dbname=appdb user=app_reader";

    QueryContext *ctx = create_context(conninfo);
    if (!ctx) return 1;

    char line[MAX_INPUT];
    while (fgets(line, sizeof(line), stdin)) {
        line[strcspn(line, "\n")] = 0;
        if (strncmp(line, "SET ", 4) == 0) {
            char *eq = strchr(line + 4, '=');
            if (eq) {
                *eq = '\0';
                add_parameter(ctx, line + 4, eq + 1);
            }
        } else if (strncmp(line, "RESET ", 6) == 0) {
            process_reset(ctx, atoi(line + 6));
        } else if (strncmp(line, "QUERY ", 6) == 0) {
            execute_query(ctx, line + 6);
        } else if (strcmp(line, "QUIT") == 0) {
            break;
        }
    }

    for (int i = 0; i < ctx->count; i++) {
        if (ctx->params[i]) ctx->params[i]->cleanup(ctx->params[i]);
    }
    PQfinish(ctx->conn);
    free(ctx->params);
    free(ctx);
    return 0;
}
